package com.hs.jxc.inv.service;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.inv.api.InventoryApi;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.imports.ImportHandler;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class InventoryImportHandler implements ImportHandler {
 private final JdbcTemplate jdbc;private final InventoryApi inventory;private final InventoryDocuments documents;private final com.hs.jxc.md.api.MasterProductApi products;
 public InventoryImportHandler(JdbcTemplate jdbc,InventoryApi inventory,InventoryDocuments documents,com.hs.jxc.md.api.MasterProductApi products){this.jdbc=jdbc;this.inventory=inventory;this.documents=documents;this.products=products;}
 public List<String> types(){return List.of("OPENING_STOCK","STOCK_LIMIT");}
 public List<String> columns(String type){return type.equals("OPENING_STOCK")?List.of("bookId","warehouseCode","productCode","qty","unitCost","batchNo","refNo","sourceDate"):List.of("warehouseCode","productCode","minQty","maxQty","alertEnabled");}
 private long resolve(String sql,Object...args){var ids=jdbc.queryForList(sql,Long.class,args);if(ids.size()!=1)throw Inputs.bad("导入档案不存在、未启用或不唯一");return ids.getFirst();}
 private BigDecimal amount(Object value){return Inputs.decimal(value,4,new BigDecimal("999999999999"));}
 // The cutoff does not change opening-source identity; native batches also cover older date-prefixed claims.
 public Row validate(Access a,String type,LocalDate cutoff,int number,Map<String,Object> raw){a.require(type.equals("OPENING_STOCK")?"inv:stock:view":"inv:limit:config");long wh=resolve("SELECT id FROM org_warehouse WHERE country_id=? AND code=? AND status='ENABLED'",a.requireCountry(),Inputs.required(raw,"warehouseCode"));if(!a.scope().all()&&!a.scope().warehouses().contains(wh))throw ApiException.notFound();long p=resolve("SELECT p.id FROM md_product p JOIN md_country_sku s ON s.product_id=p.id WHERE s.country_id=? AND p.product_code=? AND s.status='ENABLED' AND p.status='ENABLED'",a.requireCountry(),Inputs.required(raw,"productCode"));var values=new LinkedHashMap<String,Object>();values.put("warehouseId",wh);values.put("productId",p);
  if(type.equals("STOCK_LIMIT")){var min=raw.get("minQty")==null?null:amount(raw.get("minQty"));var max=raw.get("maxQty")==null?null:amount(raw.get("maxQty"));if(min!=null&&min.signum()<0||max!=null&&max.signum()<0||min!=null&&max!=null&&min.compareTo(max)>0)throw Inputs.bad("库存上下限不合法");values.put("minQty",min);values.put("maxQty",max);values.put("alertEnabled",!Boolean.FALSE.equals(raw.get("alertEnabled")));return new Row(number,values,wh+":"+p);}
  if(cutoff==null)throw Inputs.bad("期初必须填写截止日期");var sourceDate=LocalDate.parse(Inputs.required(raw,"sourceDate"));if(sourceDate.isAfter(cutoff))throw Inputs.bad("截止日期后的业务不能计入期初");String ref=Inputs.required(raw,"refNo"),batch=Inputs.required(raw,"batchNo");if(ref.length()>100||batch.length()>100)throw Inputs.bad("来源或批次编号过长");long book=raw.get("bookId")==null?resolve("SELECT b.id FROM fin_book b JOIN org_warehouse w ON w.country_id=b.country_id AND (w.entity_id=b.entity_id OR b.entity_id IS NULL) WHERE w.country_id=? AND w.id=? AND b.status='ACTIVE'",a.requireCountry(),wh):Inputs.id(raw.get("bookId"));if(!a.canBook(book))throw ApiException.notFound();if(jdbc.queryForObject("SELECT count(*) FROM fin_book b JOIN org_warehouse w ON w.country_id=b.country_id AND (w.entity_id=b.entity_id OR b.entity_id IS NULL) WHERE w.country_id=? AND w.id=? AND b.id=?",Integer.class,a.requireCountry(),wh,book)!=1)throw ApiException.notFound();if(jdbc.queryForObject("SELECT count(*) FROM inv_batch WHERE country_id=? AND book_id=? AND source_type='OPENING_STOCK' AND opening_warehouse_id=? AND product_id=? AND opening_batch_no=?",Integer.class,a.requireCountry(),book,wh,p,batch)>0)throw new ApiException(409,"SYS_IMPORT_REFERENCE_EXISTS","该来源批次已有系统库存，不能覆盖");var qty=amount(raw.get("qty"));var cost=amount(raw.get("unitCost"));if(qty.signum()<=0||cost.signum()<0)throw Inputs.bad("数量须正数且单位成本必须明确非负");values.put("baseUnit",products.reference(a.requireCountry(),p).baseUnit());values.put("bookId",book);values.put("qty",qty);values.put("unitCost",cost);values.put("batchNo",batch);values.put("refNo",ref);values.put("sourceDate",sourceDate.toString());return new Row(number,values,book+":"+wh+":"+p+":"+batch);
 }
 public Target apply(RequestContext c,Access a,Batch batch,Row row){var v=row.values();if(batch.type().equals("STOCK_LIMIT")){documents.saveLimits(c,Map.of("items",List.of(v)),ImportHandler.commandKey(batch,row,"limit"));long id=resolve("SELECT id FROM inv_stock_limit WHERE country_id=? AND warehouse_id=? AND product_id=?",a.requireCountry(),v.get("warehouseId"),v.get("productId"));return new Target("INV_LIMIT",id);}long source=resolve("SELECT id FROM sys_import_row WHERE country_id=? AND batch_id=? AND row_no=?",a.requireCountry(),batch.id(),row.rowNo());var result=inventory.opening(c,new InventoryApi.Opening(Inputs.id(v.get("bookId")),Inputs.id(v.get("warehouseId")),Inputs.id(v.get("productId")),amount(v.get("qty")),amount(v.get("unitCost")),new InventoryApi.Source("OPENING_STOCK",batch.id(),source,v.get("refNo").toString()),batch.cutoffDate(),v.get("batchNo").toString()));return new Target("INV_BATCH",result.id());}
}
